import{_ as e,o as i,c as n,a1 as t}from"./chunks/framework.CblolBb6.js";const m=JSON.parse('{"title":"Hari 3 - Backend, Autentikasi, dan Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"hari-3/index.md","filePath":"hari-3/index.md"}'),r={name:"hari-3/index.md"};function d(o,a,l,s,k,u){return i(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="hari-3-backend-autentikasi-dan-deployment" tabindex="-1">Hari 3 - Backend, Autentikasi, dan Deployment <a class="header-anchor" href="#hari-3-backend-autentikasi-dan-deployment" aria-label="Permalink to &quot;Hari 3 - Backend, Autentikasi, dan Deployment&quot;">​</a></h1><p>Hari ketiga menutup rantai pengembangan. Sesi pagi menghubungkan aplikasi ke basis data, membangun CRUD API, lalu mengamankan API itu dengan NextAuth. Sesi siang memindahkan seluruh aplikasi dari laptop ke server: membuat VM di Google Cloud, membangun image Docker, menjalankan GeoServer serta Nginx di dalamnya, dan memasang Reverse Proxy.</p><h2 id="jadwal-hari-3" tabindex="-1">Jadwal Hari 3 <a class="header-anchor" href="#jadwal-hari-3" aria-label="Permalink to &quot;Jadwal Hari 3&quot;">​</a></h2><p>Mengacu pada susunan acara pelatihan periode 15 sampai 18 September 2026.</p><table tabindex="0"><thead><tr><th>Waktu</th><th>Kegiatan</th><th>Materi di halaman ini</th></tr></thead><tbody><tr><td>08.00 - 10.00</td><td>Membuat koneksi database dengan ORM, membuat CRUD API</td><td><a href="#backend-dan-autentikasi">Backend dan Autentikasi</a></td></tr><tr><td>10.15 - 12.00</td><td>Penjelasan NextAuth, session, hashing, enkripsi. Membuat session, logika hak akses, konfigurasi middleware</td><td><a href="#backend-dan-autentikasi">Backend dan Autentikasi</a></td></tr><tr><td>13.00 - 14.30</td><td>Penjelasan GCP, VM, Docker dan Nginx</td><td><a href="#deployment-ke-google-cloud">Deployment ke Google Cloud</a></td></tr><tr><td>14.45 - 16.00</td><td>Pembuatan VM dan Artifact Registry, build project Next.js di Docker, konfigurasi Reverse Proxy Nginx</td><td><a href="#deployment-ke-google-cloud">Deployment ke Google Cloud</a></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Dua blok belum punya berkas materi</p><p>Penjelasan CRUD API pada blok pagi dan penjelasan GCP, VM, Docker serta Nginx sebelum sesi praktik belum punya halaman di repositori ini. Keduanya saat ini disampaikan langsung oleh instruktur. Halaman ini akan diperbarui begitu materinya tersedia.</p></div><h2 id="backend-dan-autentikasi" tabindex="-1">Backend dan Autentikasi <a class="header-anchor" href="#backend-dan-autentikasi" aria-label="Permalink to &quot;Backend dan Autentikasi&quot;">​</a></h2><p>Bagian ini menghubungkan aplikasi Next.js ke basis data dan menambahkan sistem login.</p><ol><li><a href="/Pelatihan-WebGIS-BIG/hari-3/backend-auth/prisma-api-login.html">Konfigurasi Prisma dan Membuat API Login</a> - memasang Prisma ORM, menyambungkannya ke PostgreSQL, dan membuat endpoint login.</li><li><a href="/Pelatihan-WebGIS-BIG/hari-3/backend-auth/nextauth-access-token.html">Konfigurasi Access Token dan NextAuth</a> - membuat session, mengatur hak akses, dan mengonfigurasi middleware.</li></ol><h2 id="deployment-ke-google-cloud" tabindex="-1">Deployment ke Google Cloud <a class="header-anchor" href="#deployment-ke-google-cloud" aria-label="Permalink to &quot;Deployment ke Google Cloud&quot;">​</a></h2><p>Halaman-halaman berikut adalah satu rangkaian. Berkas yang dibuat pada tahap pertama dipakai pada tahap kedua, dan konfigurasi Nginx yang dibuat pada tahap pertama baru berguna setelah sertifikat pada tahap ketiga terbit.</p><ol><li><a href="/Pelatihan-WebGIS-BIG/hari-3/praktik-11-deploy/konfigurasi-project.html">Konfigurasi Project</a> - menyiapkan <code>docker-compose.yml</code>, <code>nginx.conf</code>, <code>.env.example</code>, dan pemeriksa konfigurasi di repositori proyek.</li><li><a href="/Pelatihan-WebGIS-BIG/hari-3/praktik-11-deploy/google-cloud-platform.html">Google Cloud Platform</a> - menyiapkan Cloud Shell, service account, VM, IP statis, Docker, lalu menjalankan GeoServer dan Nginx.</li><li><a href="/Pelatihan-WebGIS-BIG/hari-3/praktik-11-deploy/subdomain.html">Penambahan Subdomain</a> - mengarahkan subdomain ke IP statis VM dan menerbitkan sertifikat Let&#39;s Encrypt.</li></ol><h2 id="yang-perlu-disiapkan-peserta" tabindex="-1">Yang Perlu Disiapkan Peserta <a class="header-anchor" href="#yang-perlu-disiapkan-peserta" aria-label="Permalink to &quot;Yang Perlu Disiapkan Peserta&quot;">​</a></h2><ul><li>Akses ke Google Cloud project dari koordinator, beserta identitas peserta untuk <code>PARTICIPANT_ID</code>.</li><li>Akun GitHub berisi fork repositori proyek. Berkas <code>cloudbuild.yaml</code> dan pemeriksa konfigurasi diambil dari sana.</li><li>Domain dari penyelenggara beserta subdomain yang sudah ditetapkan, dipakai pada <a href="/Pelatihan-WebGIS-BIG/hari-3/praktik-11-deploy/subdomain.html">Penambahan Subdomain</a>.</li><li>Berkas <code>.env.example</code> dari instruktur, dipakai pada <a href="/Pelatihan-WebGIS-BIG/hari-3/praktik-11-deploy/konfigurasi-project.html">Konfigurasi Project</a>.</li></ul><h2 id="hasil-akhir-hari-3" tabindex="-1">Hasil Akhir Hari 3 <a class="header-anchor" href="#hasil-akhir-hari-3" aria-label="Permalink to &quot;Hasil Akhir Hari 3&quot;">​</a></h2><p>Di akhir hari, Geoportal sudah berjalan di alamat <code>http://IP_EKSTERNAL_VM/portal</code>, sistem login berfungsi, dan GeoServer dapat diakses dari halaman yang sama. Setelah tahap subdomain selesai, alamat itu berubah menjadi <code>https://SUBDOMAIN/portal</code> dan sertifikatnya dipercaya browser.</p>',16)])])}const p=e(r,[["render",d]]);export{m as __pageData,p as default};
